fn decode<T>(label: &str, raw: &str) -> TestResult<T>
where
    T: serde::de::DeserializeOwned,
{
    match serde_json::from_str(raw) {
        Ok(value) => Ok(value),
        Err(error) => Err(fail(format!("golden {label}: {error}"))),
    }
}

fn fail(label: String) -> Box<dyn std::error::Error> {
    Box::new(std::io::Error::other(label))
}

pub(super) fn append(store: &Store) -> TestResult<CanonicalPerformance> {
    let meet: CanonicalMeet = decode("meet", GOLDEN_MEET)?;
    let event: CanonicalEvent = decode("event", GOLDEN_EVENT)?;
    let team: CanonicalTeam = decode("team", GOLDEN_TEAM)?;
    let athlete: CanonicalAthlete = decode("athlete", GOLDEN_ATHLETE)?;
    let observation: SourceObservation = decode("observation", GOLDEN_OBSERVATION)?;
    let performance: CanonicalPerformance = decode("performance", GOLDEN_PERFORMANCE)?;
    store.append(Table::Meets, &meet)?;
    store.append(Table::Events, &event)?;
    store.append(Table::Teams, &team)?;
    store.append(Table::Athletes, &athlete)?;
    store.append(Table::SourceObservations, &observation)?;
    store.append(Table::Performances, &performance)?;
    Ok(performance)
}
